H,W=len(I),len(I[0])
# find connected components of 3s and 6s
import numpy as np
from collections import deque
def comps(mask):
    seen=np.zeros_like(mask); out=[]
    for i in range(H):
        for j in range(W):
            if mask[i,j] and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=1; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=1; q.append((ny,nx))
                out.append(cells)
    return out
c3=comps(np.array(I)==3); c6=comps(np.array(I)==6)
print(len(c3), len(c6))
for k,cells in enumerate(c3):
